    String queryString = "SELECT DISTINCT * { ?s ?p 123 } ORDER BY ?s ?p";
    String opExpectedString = "(reduced\n" + "  (order (?s ?p)\n" + "    (bgp (triple ?s ?p 123))))";
    testQuery(queryString, tDistinctToReduced, opExpectedString);
}

