    // Has a blocking optional pattern for the join strategy.
    String qs = StrUtils.strjoinNL("select *", "where {", "  { select * { ?id ?p ?label } order by ?label limit 5 }", "  OPTIONAL { OPTIONAL { ?s ?p ?label }}", "}");
    String expected = StrUtils.strjoinNL("(leftjoin", "  (top (5 ?label)", "    (bgp (triple ?id ?p ?label)))", "  (conditional", "    (table unit)", "    (bgp (triple ?s ?p ?label))))");
