}

// JENA-1280 : Test that variables in FILTER EXISTS do not block sequence
@Test
public void joinSequence_01() {
    String queryString = StrUtils.strjoinNL("SELECT * {", "  ?s ?p ?o", "  GRAPH ?g {", "    ?s1 ?p ?o1 .", "    FILTER EXISTS {  [] ?p ?unique } .", "  }", "}");
    // For reference, which is ...
    String x = StrUtils.strjoinNL("(join", "    (bgp (triple ?s ?p ?o))", "    (graph ?g", "      (filter (exists (bgp (triple ??0 ?p ?unique)))", "        (bgp (triple ?s1 ?p ?o1)))))");
    String optimized = StrUtils.strjoinNL("(sequence", "    (bgp (triple ?s ?p ?o))", "    (graph ?g", "      (filter (exists (bgp (triple ??0 ?p ?unique)))", "        (bgp (triple ?s1 ?p ?o1)))))");
    check(queryString, optimized);
}

