    //@formatter:off
    test(StrUtils.strjoinNL("(project (?y)", "  (filter (exprlist ?x)", "    (extend (?x true)", "      (table unit))))"), "(project (?y)", "  (filter (exprlist true)", "    (table unit)))");
    //@formatter:on
}

@Test
public void filter_02() {
