    //@formatter:off
    test(StrUtils.strjoinNL("(project (?z)", "  (filter (exprlist ?x)", "    (extend ((?x true) (?y false))", "      (table unit))))"), "(project (?z)", "  (filter (exprlist true)", "    (table unit)))");
