    String ops1 = StrUtils.strjoinNL("(filter (= ?x <http://example/x>)", "    (conditional", "      (table unit)", "      (assign ((?x <http://example/x>))", "        (bgp (triple <http://example/x> <http://example/q> ?o)))))");
    TestOptimizer.check(qs, ops1);
}

