@Test
public void testNodeSortKey4() {
    // Collation sort order for Finnish
    final String collation = "fi";
    String[] ordered = new String[] { "tsahurin kieli", "tšekin kieli", "tulun kieli", "töyhtöhyyppä" };
    // Query String
    final String queryString = "PREFIX skos: <http://www.w3.org/2004/02/skos/core#>\n" + "PREFIX arq: <http://jena.apache.org/ARQ/function#>\n" + "SELECT ?label WHERE {\n" + "   VALUES ?label { \"tulun kieli\"@es \"tšekin kieli\" \"tsahurin kieli\"@en \"töyhtöhyyppä\"@fi }\n" + "}\n" + "ORDER BY arq:collation(\"" + collation + "\", ?label)";
    Model model = ModelFactory.createDefaultModel();
    Query query = QueryFactory.create(queryString);
    List<String> result = new LinkedList<>();
    try (QueryExecution qExec = QueryExecutionFactory.create(query, model)) {
        ResultSet results = qExec.execSelect();
        while (results.hasNext()) {
            QuerySolution solution = results.nextSolution();
            result.add(solution.getLiteral(solution.varNames().next()).getLexicalForm());
        }
    }
    assertArrayEquals(ordered, result.toArray(new String[0]));
}

