@Test
public void testComp_2_3() {
    int x = NodeValue.compareAlways(nvInt2, nvInt3);
    assertTrue("2 should be value-less than 3", Expr.CMP_LESS == x);
    int y = NodeUtils.compareRDFTerms(nInt2, nInt3);
