@Test
public void testFunctionCollationExec() {
    collation function = new collation();
    NodeValue collation = NodeValue.makeString("fi");
    final String[] unordered = new String[] { "tšekin kieli", "tulun kieli", "töyhtöhyyppä", "tsahurin kieli", "tsahurin kieli", "tulun kieli" };
    String[] ordered = new String[] { "'tsahurin kieli'", "'tsahurin kieli'", "'tšekin kieli'", "'tulun kieli'", "'tulun kieli'", "'töyhtöhyyppä'" };
    // tests collation sort order with Danish words, but New Zealand English collation rules
    List<NodeValue> nodeValues = new LinkedList<>();
    for (String string : unordered) {
        nodeValues.add(function.exec(collation, NodeValue.makeString(string)));
    }
    nodeValues.sort((NodeValue o1, NodeValue o2) -> NodeValue.compare(o1, o2));
    List<String> result = new LinkedList<>();
    for (NodeValue nv : nodeValues) {
        String s = nv.toString();
        result.add(s);
    }
    assertArrayEquals(ordered, result.toArray(new String[0]));
}

@Test
public void test_function_expansion_01() {
    Expr e = new ExprVar("x");
    UserDefinedFunctionFactory.getFactory().add("http://example/simple", e, new ArrayList<>(e.getVarsMentioned()));
    UserDefinedFunction f = (UserDefinedFunction) UserDefinedFunctionFactory.getFactory().create("http://example/simple");
    f.build("http://example/simple", new ExprList(new NodeValueBoolean(true)));
    Expr actual = f.getActualExpr();
    Assert.assertFalse(e.equals(actual));
    Assert.assertEquals(0, actual.getVarsMentioned().size());
    Assert.assertEquals(new NodeValueBoolean(true), actual);
}

