    Txn.executeWrite(counter, () -> counter.set(91));
    Txn.executeWrite(counter, () -> {
        assertEquals("In txn, value()", 91, counter.value());
        assertEquals("In txn, read()", 91, counter.read());
        counter.inc();
        Txn.executeWrite(counter, () -> {
            assertEquals("In txn, value()", 91, counter.value());
            assertEquals("In txn, get()", 92, counter.read());
            counter.inc();
