}

@Test
public void txnThread_11() {
    long x1 = counter.get();
    Txn.executeWrite(counter, () -> {
        counter.inc();
        // Read the "before" state
        ThreadAction t = ThreadTxn.threadTxnRead(counter, () -> {
            long z1 = counter.get();
            assertEquals("Thread read", x1, z1);
        });
        counter.inc();
        t.run();
    });
    long x2 = counter.get();
    assertEquals("after", x1 + 2, x2);
}

