    awaitUntil(1, 500, MILLISECONDS);
    alarmClock.cancel(a2);
    alarmClock.release();
}

@Test
public void alarm_04() {
    AlarmClock alarmClock = new AlarmClock();
    Alarm a1 = alarmClock.add(callback, 10);
    Alarm a2 = alarmClock.add(callback, 20);
    awaitUntil(2, 500, MILLISECONDS);
    alarmClock.release();
}

@Test
public void alarm_05() {
    AlarmClock alarmClock = new AlarmClock();
    Alarm a = alarmClock.add(callback, 50);
    alarmClock.reset(a, 20000);
    sleep(150);
    // Did not go off.
    assertEquals(0, count.get());
    alarmClock.cancel(a);
    alarmClock.release();
}

// Linear search is really there to test binary search.
@Test
public void linear1() {
    int[] data = { 1, 2, 3 };
    IntBuffer b = make(data);
    int idx = 0;
    idx = Alg.linearSearch(b, 1);
    assertEquals(0, idx);
    idx = Alg.linearSearch(b, 2);
    assertEquals(1, idx);
    idx = Alg.linearSearch(b, 3);
    assertEquals(2, idx);
}

@Test
public void linear2() {
    int[] data = { 2, 4, 6 };
    IntBuffer b = make(data);
    int idx = 0;
    idx = Alg.linearSearch(b, 1);
    assertEquals(-1, idx);
    idx = Alg.linearSearch(b, 3);
    assertEquals(-2, idx);
    idx = Alg.linearSearch(b, 5);
    assertEquals(-3, idx);
    idx = Alg.linearSearch(b, 7);
    assertEquals(-4, idx);
}

@Test
