}

@Test
public void linear4() {
    int[] data = { 9 };
    IntBuffer b = make(data);
    int idx;
    idx = Alg.linearSearch(b, 1);
    assertEquals(-1, idx);
    idx = Alg.linearSearch(b, 9);
    assertEquals(0, idx);
    idx = Alg.linearSearch(b, 100);
    assertEquals(-2, idx);
}

@Test
public void linear5() {
    int[] data = { 2, 4, 6, 8, 10 };
    IntBuffer b = make(data);
    int idx = 0;
    idx = Alg.linearSearch(b, 1, 4, 6);
    assertEquals(2, idx);
    idx = Alg.linearSearch(b, 1, 4, 5);
    assertEquals(-3, idx);
    idx = Alg.linearSearch(b, 1, 4, 2);
    assertEquals(-2, idx);
    idx = Alg.linearSearch(b, 1, 4, 10);
    assertEquals(-5, idx);
}

