@Test
public void cache_10() {
    Cache<Integer, String> cache = CacheFactory.createOneSlotCache();
    String str = cache.getIfPresent(1);
    assertNull(str);
    cache.put(1, "1");
    str = cache.getIfPresent(1);
    assertEquals("1", str);
    cache.put(2, "2");
    str = cache.getIfPresent(1);
    assertNull(str);
    cache.put(1, "1");
    str = cache.getIfPresent(2);
    assertNull(str);
    str = cache.getIfPresent(1);
    assertEquals("1", str);
}

