    Record r = RecordLib.intToRecord(0x32);
    Record r2 = search(bpr, r);
    assertTrue(Record.keyEQ(r, r2));
    r = bpr.getLowRecord();
    r2 = search(bpr, r);
    assertTrue(Record.keyEQ(r, r2));
    r = bpr.getHighRecord();
    r2 = search(bpr, r);
    assertTrue(Record.keyEQ(r, r2));
    bpr.release();
}

