    assertFalse(b);
    assertEquals(0, counter1.get());
    // Now run thread
    ttxn.run();
    assertEquals(1, counter1.get());
    Txn.executeWrite(unit, () -> {
    });
    b = txnMgr.tryExclusiveMode(false);
    assertTrue(b);
}

