@Test
public void testOptionalWithUnionRestriction() {
    // It was possible to pass all other tests, but still generate incorrect algebra
    // when a query contained an OPTIONAL pattern, and was also retricted by a UNION of patterns
    // This test ensures this specific edge case is validated
    testTransform(// SPARQL to Test
    "CONSTRUCT {
" + "  ?publication a ?type .
" + "  ?publication <http://localhost/access> ?access .
" + "} WHERE {
" + "  ?publication a ?type .
" + "  OPTIONAL { ?publication <http://localhost/access> ?access . }
" + "  {
" + "    ?publication a <http://localhost/Report>  .
" + "  }
" + "  UNION
" + "  {
" + "    ?publication a <http://localhost/AcademicArticle>  .
" + "  }
" + "}
", // Target Op
    "(join
" + "    (leftjoin
" + "      (bgp
" + "        (triple ?publication <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> ?type)
" + "      )
" + "      (bgp
" + "        (triple ?publication <http://localhost/access> ?access)
" + "      ))
" + "  (union
" + "    (bgp (triple ?publication <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <http://localhost/Report>))
" + "    (bgp (triple ?publication <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <http://localhost/AcademicArticle>))
" + "    ))

");
}

