@Test
public void testScopeOrder() {
    ScopeBase base = new ScopeBase();
    SqlTable quads = new SqlTable("quads");
    base.setColumnForVar(Var.alloc("s"), new SqlColumn(quads, "s"));
    base.setColumnForVar(Var.alloc("p"), new SqlColumn(quads, "p"));
    base.setColumnForVar(Var.alloc("o"), new SqlColumn(quads, "o"));
    Iterator<Var> vars = base.getVars().iterator();
    Var var;
    Assert.assertTrue(vars.hasNext());
    var = vars.next();
    Assert.assertTrue("s".equals(var.getVarName()));
    Assert.assertTrue(vars.hasNext());
    var = vars.next();
    Assert.assertTrue("p".equals(var.getVarName()));
    Assert.assertTrue(vars.hasNext());
    var = vars.next();
    Assert.assertTrue("o".equals(var.getVarName()));
    Assert.assertFalse(vars.hasNext());
    Iterator<ScopeEntry> scopes = base.findScopes().iterator();
    ScopeEntry entry;
    Assert.assertTrue(scopes.hasNext());
    entry = scopes.next();
    Assert.assertTrue("s".equals(entry.getVar().getVarName()));
    Assert.assertTrue("s".equals(entry.getColumn().getColumnName()));
    Assert.assertTrue(scopes.hasNext());
    entry = scopes.next();
    Assert.assertTrue("p".equals(entry.getVar().getVarName()));
    Assert.assertTrue("p".equals(entry.getColumn().getColumnName()));
    Assert.assertTrue(scopes.hasNext());
    entry = scopes.next();
    Assert.assertTrue("o".equals(entry.getVar().getVarName()));
    Assert.assertTrue("o".equals(entry.getColumn().getColumnName()));
    Assert.assertFalse(scopes.hasNext());
}

@Test
public void testRewriteDistinctAsGroup() {
    Query query = QueryFactory.create("PREFIX  :     <http://example/>\n" + "PREFIX  arq:  <urn:x-arq:>\n" + "\n" + "SELECT  *\n" + "WHERE\n" + "  { GRAPH arq:UnionGraph\n" + "      { ?s  ?p  ?o }\n" + "  }\n");
    StoreDesc storeDesc = new StoreDesc(LayoutType.LayoutTripleNodesHash, DatabaseType.MySQL);
    Store store = StoreFactory.create(storeDesc);
    QueryEngineSDB qe = new QueryEngineSDB(store, query);
    String sql = SDB_QC.toSqlString((OpSQL) qe.getOp(), new SDBRequest(store, query));
    // Ensure the SQL contains an GROUP BY clause
    Assert.assertTrue(sql.contains("GROUP BY"));
}

@Test
public void testRewriteOrder() {
    Query query = QueryFactory.create("PREFIX  :     <http://example/>\n" + "PREFIX  arq:  <urn:x-arq:>\n" + "\n" + "SELECT  *\n" + "WHERE\n" + "  { GRAPH arq:UnionGraph\n" + "      { ?s  ?p  ?o }\n" + "  }\n" + "ORDER BY ?s\n" + "LIMIT 10\n");
    StoreDesc storeDesc = new StoreDesc(LayoutType.LayoutTripleNodesHash, DatabaseType.MySQL);
    Store store = StoreFactory.create(storeDesc);
    Context context = SDB.getContext().copy();
    // Turn on ORDER BY rewriting
    context.set(SDB.optimizeOrderClause, true);
    QueryEngineSDB qe = new QueryEngineSDB(new DatasetGraphSDB(store, context), query, BindingRoot.create(), context);
    String sql = SDB_QC.toSqlString((OpSQL) qe.getOp(), new SDBRequest(store, query));
    // Ensure the SQL contains an ORDER BY clause
    Assert.assertTrue(sql.contains("ORDER BY"));
}

