// Test transactions effective.
@Test
public void sparql_txn_1() {
    Dataset dataset = create();
    update(dataset, "INSERT DATA { <x:s> <x:p> <x:o> }");
    dataset.begin(ReadWrite.READ);
    try {
        int n = count(dataset);
        assertEquals(1, n);
        n = count(dataset, "SELECT * { <x:s> <x:p> <x:o>}");
        assertEquals(1, n);
    } finally {
        dataset.end();
    }
}

